    summary:
      'Hai bên lao vào trận đối công ngay từ khai cuộc: Đen thí Xe lấy Pháo và Mã, rồi dùng Pháo ăn Tốt giữa chiếu Tướng. Lữ Khâm gan dạ dỡ Pháo đầu, chấp nhận để Pháo Đen đứng "không đầu" trước mặt Tướng mình. Trận chiến đổi chiều nhiều lần; đến nước 30 Đỏ lại đổi Xe lấy hai quân, đưa ván cờ về thế Xe – Mã – Pháo mỗi bên, nhưng Đen đã mất một Tượng. Không muốn hòa, Trịnh Hỏa Thiêm đưa Tướng ra đánh tàn cuộc; Lữ Khâm kiên nhẫn ăn Tốt, phá Sĩ Tượng, rồi trừng phạt một sai lầm của đối thủ bằng sự phối hợp Xe – Mã.',
