      '11': 'Xe bình sang f1, mở cột f nhắm thẳng Sĩ f9 – từ đây Đỏ dồn toàn lực sang cánh phải của Đen.',
      '11...': 'Pháo giữa dạt sang d7, chuẩn bị lao xuống hàng 1 quấy rối. Nhưng Pháo rời cột e cũng để trống trung lộ cho Đỏ.',
