      '29...': 'Pháo lùi về g8 – "lùi để tiến": Pháo đứng trên cột g, chỉ còn thiếu một cái ngòi để bắn xuống Tượng g0.',
      '30': 'Pháo về giữa dọa bắn Tốt đầu e6. Đỏ mải tấn công mà không thấy mối nguy trên cột g.',
