    difficulty: 4,
    context:
      'Năm 1993, Hứa Ngân Xuyên mới 18 tuổi đã giành chức vô địch cá nhân toàn quốc đầu tiên. Ván này là một bước ngoặt trên con đường ấy, được chính Hứa Ngân Xuyên bình giải trong tập "Ngân Xuyên kỳ lộ" (银川棋路). Theo lời kể của anh, sau 8 vòng, đại sư Lưu Điện Trung (Hà Bắc) – người thầy cũ của nhà vô địch nữ Hồ Minh – đang dẫn đầu một mình với 5 thắng 3 hòa (6,5 điểm); bám sát với 6 điểm là Lữ Khâm, Trang Ngọc Đằng, Triệu Quốc Vinh, Bốc Phụng Ba và Hứa Ngân Xuyên. Theo nguyên tắc ghép cặp điểm cao gặp nhau, vòng 9 Hứa Ngân Xuyên phải gặp người dẫn đầu.',
    summary:
      'Lưu Điện Trung tung ra một "phi đao" ở nước 10, đưa Xe chồng lên cột h để ép đổi Xe – nhưng chính Hứa Ngân Xuyên nhận xét rằng nước mới ấy chưa chín, vì nó cởi trói cho cánh trái của Đen. Đen kiên nhẫn đẩy Tốt biên mở cột a, đưa hai Mã vào trung tâm. Khi Đỏ lùi Pháo một cách thiếu cẩn trọng (nước 24), Hứa Ngân Xuyên thí Mã ăn Tượng, dùng Xe bắt đôi để ăn nốt Tượng thứ hai, rồi lấy lại quân và từng bước ăn thêm. Thắng ván này, chàng trai 18 tuổi cùng Lữ Khâm vươn lên dẫn đầu giải.',
